const CACHE='ombaliz-needs-render-v1';self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['vendor/pdf-lib.min.js','vendor/fontkit.min.js','vendor/regular.ttf','vendor/bold.ttf','pdf-report.js','phone.js','qr-application.png','./','index.html','style.css','app.js','data.js','logo.png','manifest.webmanifest','icon-192.png','icon-512.png']))));self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===location.origin)e.respondWith(fetch(e.request).catch(()=>caches.match(e.request))) });
